--The conversation window can behave very strange depending on different situations:
--Typically, a conversation with options (1, 2, ...) is rendered all in the same Batch2D event
--Typically, a normal conversation (with continue button) is rendered in two separate Batch2D event:
-- - The button & text in one
-- - The background & frame in another
--However, this is not always true (especially during quests), when e.g. the continue button is rendered in
--a separate event from the rest.

---@class ConversationOption
---@field data string
---@field pos OptionPosition

---@class OptionPosition
---@field x integer
---@field y integer
---@field width integer
---@field height integer

---@class ConversationModule
local ConversationModule = {}

-- Tries to read the options from a conversation window
-- If nothing is found, nil is returned
-- The position, width and height are already scaled according to interface scaling
---Read the possible options from the screen
---@param event any Batch2D event
---@param gamewindowsize integer
---@param includeNumbers boolean
---@return nil|ConversationOption[]
function ConversationModule:readoptions(event, gamewindowsize, includeNumbers)
	local vertexcount = event:vertexcount()
	local verticesperimage = event:verticesperimage()

	-- start by finding the top-conversation bar and the close button
	local topBarIndex = nil
	local bottomBarIndex = nil
	local topBarX, topBarY, topBarWidth
	local bottomBarY
	local closeButtonFound = false
	local conversationBackgroundFound = false

	for i = 1, vertexcount, verticesperimage do
		local ax, ay, aw, ah, _, _ = event:vertexatlasdetails(i)
		-- No need to search when everything is found already
		if topBarIndex ~= nil and bottomBarIndex ~= nil and closeButtonFound and conversationBackgroundFound then
			break
		end

		-- Search the close button (only present with options)
		if
			not closeButtonFound
			and aw == self.closeButtonSize[1]
			and ah == self.closeButtonSize[2]
			and (
				event:texturecompare(ax, ay + 5, self.closeButtonTexture)
				or event:texturecompare(ax, ay + 5, self.closeButtonHoverTexture)
			)
		then
			closeButtonFound = true
			goto continue
		end

		if
			not conversationBackgroundFound
			and aw == self.conversationBackgroundSize[1]
			and ah == self.conversationBackgroundSize[2]
			and event:texturecompare(ax, ay + 1, self.conversationBackgroundTexture)
		then
			conversationBackgroundFound = true
			goto continue
		end

		-- if not conversationBackgroundFound and aw == self.conversationBackgroundSize2[1] and ah == self.conversationBackgroundSize2[2] and event:texturecompare(ax, ay + 1, self.conversationBackgroundTexture2) then
		--   conversationBackgroundFound = true
		--   goto continue
		-- end

		-- Simple match for sizes
		if
			(aw ~= self.conversationTopBarSize[1] or ah ~= self.conversationTopBarSize[2])
			and (aw ~= self.conversationBottomBarSize[1] or ah ~= self.conversationBottomBarSize[2])
		then
			goto continue
		end

		-- Compare for top bar texture if not found yet
		if topBarIndex == nil and event:texturecompare(ax, ay + 3, self.conversationTopBarTexture) then
			topBarX, topBarY = event:vertexxy(i + 2) -- top left is 3rd
			topBarWidth = event:vertexxy(i) - topBarX -- bottom-right is 1st
			topBarIndex = i
			goto continue

		-- Compare for bottom bar texture if not found yet
		elseif bottomBarIndex == nil and event:texturecompare(ax, ay + 3, self.conversationBottomBarTexture) then
			_, bottomBarY = event:vertexxy(i)
			bottomBarIndex = i
		end
		::continue::
	end

	-- Not everything was found. There is probably no conversation with options showing or something went wrong.
	if not closeButtonFound or not conversationBackgroundFound or topBarIndex == nil or bottomBarIndex == nil then
		return nil
	end

	local options = {}
	local optionNb = 0
	local size = gamewindowsize
	local scale = size / event:targetsize()

	-- Fill in the options
	for i = 1, vertexcount, verticesperimage do
		-- Every option first has its background (the blue/black rectangle), we use this as separator
		local ax, ay, aw, ah, _, _ = event:vertexatlasdetails(i)
		-- Check for separator
		if
			aw == self.optionBackgroundSize[1]
			and ah == self.optionBackgroundSize[2]
			and event:texturecompare(ax, ay + 2, self.optionBackgroundTexture)
		then
			optionNb = optionNb + 1
			if includeNumbers then
				options[optionNb] = {
					data = tostring(optionNb) .. ".",
				}
			else
				options[optionNb] = {
					data = "",
				}
			end

			-- To get the entire background, we assume the left and right handle are the next two images such that
			-- we don't need to check textures again. If it fails in the future we can simply add texture comparison here.
			local topLeftX, topLeftY = event:vertexxy(i + verticesperimage + 2) -- top-left is the 3rd vertex normally
			local bottomRightX, bottomRightY = event:vertexxy(i + 2 * verticesperimage) -- bottom-right is the 1st vertex normally
			options[optionNb].pos = {
				x = topLeftX * scale,
				y = topLeftY * scale,
				width = (bottomRightX - topLeftX) * scale,
				height = (bottomRightY - topLeftY) * scale,
			}
			goto continue
		end

		-- skip if we don't have background yet
		if optionNb == 0 then
			goto continue
		end

		local r, g, b = event:vertexcolour(i)
		if r == 0 and g == 0 and b == 0 then
			goto continue
		end

		local x, y = event:vertexxy(i)

		-- Add character to option only if it is between the top and bottom bar
		if y < topBarY or y > bottomBarY or x < topBarX or x > topBarX + topBarWidth then
			goto continue
		end

		-- Look up chat character and add if it's not nil
		local char = self:lookupchatcharacter(event, self.conversationchars, ax, ay, aw, ah)
		if char ~= nil then
			options[optionNb].data = options[optionNb].data .. char
		end

		::continue::
	end

	-- remove nb at the end
	for i, option in ipairs(options) do
		options[i].data = string.sub(option.data, 1, -3)
	end

	return options
end

---Read the text of the conversation window
---@param event any Batch2D event
---@return string
function ConversationModule:readconversation(event)
	-- Check first whether this is a conversation. It should not be inefficient since we start looking from the end
	if not self:continueButtonFound(event) then
		return ""
	end

	local vertexcount = event:vertexcount()
	local verticesperimage = event:verticesperimage()
	local text = ""

	for i = 1, vertexcount, verticesperimage do
		local ax, ay, aw, ah, _, _ = event:vertexatlasdetails(i)
		local _, _, _, alpha = event:vertexcolour(i)
		-- Ignore these double letters that are invisible
		if alpha == 0 then
			goto continue
		end

		local char = self:lookupchatcharacter(event, self.conversationchars, ax, ay, aw, ah)
		if char then
			text = text .. char
		end

		::continue::
	end

	return text
end

---Returns if we are currently in a conversation. If yes, the second argument is the position of the continue button on screen.
---@param event any Batch2d event
---@return boolean
---@return OptionPosition # Position of the continue button on screen
function ConversationModule:continueButtonFound(event)
	local vertexcount = event:vertexcount()
	local verticesperimage = event:verticesperimage()

	-- we go decrementally since it's usually at the end of the event
	for i = vertexcount - verticesperimage + 1, 1, -verticesperimage do
		local ax, ay, aw, ah, _, _ = event:vertexatlasdetails(i)
		if aw ~= self.continueButtonSize[1] or ah ~= self.continueButtonSize[2] then
			goto continue
		end

		if event:texturecompare(ax, ay + 7, self.continueButtonTexture) then
			local x1, y1 = event:vertexxy(i + 2) -- top left is 3rd
			local x2, y2 = event:vertexxy(i) -- bottom right is 1st

			return true, { x = x1, y = y1, width = x2 - x1, height = y2 - y1 }
		end
		::continue::
	end

	return false, {}
end

---Looks up the given vertexatlasdetails values in the character lookup table and returns the result
---@param event any Batch2d event
---@param chars CharData
---@param ax integer
---@param ay integer
---@param aw integer
---@param ah integer
---@return string|nil
function ConversationModule:lookupchatcharacter(event, chars, ax, ay, aw, ah)
	local t = chars[ah]
	if not t then
		return nil
	end
	while true do
		if not t then
			return nil
		end
		if type(t) == "string" then
			return t
		end
		t = t.data[event:texturedata(ax, ay + t.row, aw * 4)]
	end
end

---@class CharData
---@field [integer] string|CharRowData

---@class CharRowData
---@field row integer
---@field data { [string]: string|CharRowData }

-- initial index is the atlas height of the character.
-- table with row and data indicates that the texturedata from the given row (zero-indexed, so ay+row)
-- should be used to index the data. repeat self process until the result is not a table.
-- a nil result may indicate a non-character being rendered in chat, such as a premier badge or speech bubble.
